'use strict';
// End-to-end: real fragmented-MP4 DASH generated by ffmpeg -> our MPD parser -> engine
// (429 injection, AES-128-CBC whole-segment encryption) -> merged MP4 -> verified with ffprobe/ffmpeg.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { execFileSync, spawnSync } = require('node:child_process');
const { DOMParser } = require('@xmldom/xmldom');
const M = require('../src/lib/mpd.js');
const E = require('../src/lib/engine.js');
const Mp4 = require('../src/lib/mp4.js');

const hasFfmpeg = spawnSync('ffmpeg', ['-version']).status === 0;
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ss-e2e-'));
const BASE = 'https://example-my.sharepoint.com/dash/';

function makeDash() {
  execFileSync('ffmpeg', ['-v', 'error', '-y',
    '-f', 'lavfi', '-i', 'testsrc2=size=640x360:rate=25:duration=21',
    '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=48000:duration=21',
    '-c:v', 'libx264', '-preset', 'ultrafast', '-g', '50', '-keyint_min', '50', '-sc_threshold', '0', '-pix_fmt', 'yuv420p',
    '-c:a', 'aac', '-b:a', '96k',
    '-f', 'dash', '-seg_duration', '2', '-use_template', '1', '-use_timeline', '1',
    '-adaptation_sets', 'id=0,streams=v id=1,streams=a',
    '-init_seg_name', 'init-$RepresentationID$.m4s', '-media_seg_name', 'chunk-$RepresentationID$-$Number%05d$.m4s',
    path.join(dir, 'manifest.mpd')]);
}

function sinkToFile(file) {
  const fd = fs.openSync(file, 'w');
  let maxChunk = 0;
  return { write: async (u8) => { maxChunk = Math.max(maxChunk, u8.byteLength); fs.writeSync(fd, u8); }, close: async () => fs.closeSync(fd), get maxChunk() { return maxChunk; } };
}

function fakeFetcher(transform, opts) {
  opts = opts || {};
  let n = 0; const seen = { r429: 0, total: 0 };
  const f = async (url) => {
    seen.total++;
    if (opts.throttleEvery && ++n % opts.throttleEvery === 0) { seen.r429++; return { status: 429, retryAfter: '0', buffer: null }; }
    const rel = decodeURIComponent(new URL(url).pathname.replace('/dash/', ''));
    const file = path.join(dir, rel);
    if (!fs.existsSync(file)) return { status: 404, retryAfter: null, buffer: null };
    let data = fs.readFileSync(file);
    if (transform) data = transform(data);
    return { status: 200, retryAfter: null, buffer: data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength) };
  };
  f.seen = seen;
  return f;
}

function probe(file) {
  const out = execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'stream=codec_type,codec_name:format=duration', '-of', 'json', file]);
  return JSON.parse(out);
}
function decodeErrors(file) {
  const r = spawnSync('ffmpeg', ['-v', 'error', '-i', file, '-f', 'null', '-'], { encoding: 'utf8' });
  return (r.stderr || '').trim();
}

test('e2e', { skip: !hasFfmpeg && 'ffmpeg not installed' }, async (t) => {
  makeDash();
  const parsed = M.parseMpd(fs.readFileSync(path.join(dir, 'manifest.mpd'), 'utf8'), BASE + 'manifest.mpd', DOMParser);
  const tracks = M.selectTracks(parsed, 'av');

  await t.test('ffmpeg-generated MPD is parsed', () => {
    assert.deepEqual(tracks.map((x) => x.type), ['video', 'audio']);
    assert.ok(tracks[0].segments.length >= 10 && tracks[0].segments.length <= 12, 'video segments: ' + tracks[0].segments.length);
    assert.ok(tracks[1].segments.length >= 10);
    assert.ok(parsed.durationSec > 20 && parsed.durationSec < 22);
  });

  await t.test('plain segments + 429 retries -> one playable MP4 with video and audio', async () => {
    const out = path.join(dir, 'out-plain.mp4');
    const sink = sinkToFile(out);
    const fetcher = fakeFetcher(null, { throttleEvery: 7 });
    const msgs = [];
    const res = await E.runDownload({ tracks, fetchBytes: fetcher, sink, concurrency: 4, durationSec: parsed.durationSec, onProgress: (p) => msgs.push(p.message) });
    assert.ok(fetcher.seen.r429 > 0, 'some 429 injected');
    assert.ok(msgs.some((m) => /429/.test(m)), 'user-facing 429 message');
    assert.equal(res.tracks, 2);
    const pr = probe(out);
    assert.deepEqual(pr.streams.map((s) => s.codec_type).sort(), ['audio', 'video']);
    const dur = Number(pr.format.duration);
    assert.ok(dur > 20 && dur < 22.5, 'duration ' + dur);
    assert.equal(decodeErrors(out), '');
    // mfra present at the end (seek index)
    const b = fs.readFileSync(out);
    assert.equal(b.slice(b.length - 16 + 4, b.length - 16 + 8).toString(), 'mfro');
    // streamed: never handed the sink anything larger than one segment / the init
    assert.ok(sink.maxChunk < 2 * 1024 * 1024);
  });

  await t.test('AES-128-CBC whole-segment encryption (page key) is decrypted', async () => {
    const key = crypto.randomBytes(16), iv = crypto.randomBytes(16);
    const enc = (buf) => { const c = crypto.createCipheriv('aes-128-cbc', key, iv); return Buffer.concat([c.update(buf), c.final()]); };
    const out = path.join(dir, 'out-enc.mp4');
    const ck = await globalThis.crypto.subtle.importKey('raw', key, { name: 'AES-CBC' }, false, ['decrypt']);
    await E.runDownload({ tracks, fetchBytes: fakeFetcher(enc), sink: sinkToFile(out), concurrency: 3, durationSec: parsed.durationSec, getKey: async () => ({ key: ck, iv: new Uint8Array(iv) }) });
    const pr = probe(out);
    assert.deepEqual(pr.streams.map((s) => s.codec_type).sort(), ['audio', 'video']);
    assert.equal(decodeErrors(out), '');
    const plain = fs.readFileSync(path.join(dir, 'out-plain.mp4'));
    assert.ok(fs.readFileSync(out).equals(plain), 'byte-identical to the unencrypted run');
  });

  await t.test('encrypted without key -> clear Slovenian error', async () => {
    const key = crypto.randomBytes(16), iv = crypto.randomBytes(16);
    const enc = (buf) => { const c = crypto.createCipheriv('aes-128-cbc', key, iv); return Buffer.concat([c.update(buf), c.final()]); };
    await assert.rejects(E.runDownload({ tracks, fetchBytes: fakeFetcher(enc), sink: sinkToFile(path.join(dir, 'x.mp4')) }), /šifrirani/);
  });

  await t.test('audio only -> M4A', async () => {
    const out = path.join(dir, 'out-audio.m4a');
    await E.runDownload({ tracks: M.selectTracks(parsed, 'audio'), fetchBytes: fakeFetcher(), sink: sinkToFile(out) });
    const pr = probe(out);
    assert.deepEqual(pr.streams.map((s) => s.codec_type), ['audio']);
    assert.equal(decodeErrors(out), '');
  });

  await t.test('cancel via AbortSignal', async () => {
    const ctrl = new AbortController();
    const slow = fakeFetcher();
    const f = async (u, o) => { await new Promise((r) => setTimeout(r, 30)); return slow(u, o); };
    setTimeout(() => ctrl.abort(), 100);
    await assert.rejects(E.runDownload({ tracks, fetchBytes: f, sink: sinkToFile(path.join(dir, 'c.mp4')), signal: ctrl.signal }), /preklican/);
  });

  await t.test('permanent 403 fails with HTTP status', async () => {
    const f = async () => ({ status: 403, retryAfter: null, buffer: null });
    await assert.rejects(E.runDownload({ tracks, fetchBytes: f, sink: sinkToFile(path.join(dir, 'd.mp4')) }), /HTTP 403/);
  });

  await t.test('merged init has 2 traks with ids 1,2', () => {
    const v = fs.readFileSync(path.join(dir, 'init-0.m4s')), a = fs.readFileSync(path.join(dir, 'init-1.m4s'));
    const m = Mp4.mergeInits([new Uint8Array(v), new Uint8Array(a)], { durationSec: 21 });
    const p = Mp4.parseInit(m.bytes);
    assert.deepEqual(p.traks.map((x) => [x.trackId, x.handler]), [[1, 'vide'], [2, 'soun']]);
  });
});
